-- KANEL × ALCEDO bookings — S112 PREFLIGHT (READ-ONLY). Run immediately before the
-- S112 apply bundle; keep the output. GENERATED by scripts/release/generate_kanel_s112_release.py.
-- Go only if there is no FAIL row. The 'impact' rows say what staff will notice.
with seed(id, n) as (values ('bb000000-0000-4000-8000-000000000001'::uuid, 1), ('bb000000-0000-4000-8000-000000000002'::uuid, 2), ('bb000000-0000-4000-8000-000000000003'::uuid, 3), ('bb000000-0000-4000-8000-000000000004'::uuid, 4), ('bb000000-0000-4000-8000-000000000005'::uuid, 5), ('bb000000-0000-4000-8000-000000000006'::uuid, 6), ('bb000000-0000-4000-8000-000000000007'::uuid, 7), ('bb000000-0000-4000-8000-000000000008'::uuid, 8), ('bb000000-0000-4000-8000-000000000009'::uuid, 9), ('bb000000-0000-4000-8000-000000000010'::uuid, 10), ('bb000000-0000-4000-8000-000000000011'::uuid, 11), ('bb000000-0000-4000-8000-000000000012'::uuid, 12), ('bb000000-0000-4000-8000-000000000013'::uuid, 13), ('bb000000-0000-4000-8000-000000000014'::uuid, 14), ('bb000000-0000-4000-8000-000000000015'::uuid, 15), ('bb000000-0000-4000-8000-000000000016'::uuid, 16))
select section, "check", status, detail from (
select 1 as ord, 'ledger' as section, 'production is at S111' as "check",
  case when (select max(version) from supabase_migrations.schema_migrations) = '20261028090000' then 'PASS' else 'FAIL' end as status,
  'last migration ' || coalesce((select max(version) from supabase_migrations.schema_migrations), 'none') as detail
union all select 2, 'ledger', 'no S112 row yet',
  case when not exists (select 1 from supabase_migrations.schema_migrations where version = '20261029090000') then 'PASS' else 'FAIL' end, ''
union all select 3, * from (select * from (select 'drift', 'booking_lifecycle_notify body = S111',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_lifecycle_notify' and pg_catalog.pg_get_function_identity_arguments(p.oid) = '') = '2b03da051c6bea3c908aa13c331c5349' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_lifecycle_notify' and pg_catalog.pg_get_function_identity_arguments(p.oid) = ''), 'function missing')) x union all select * from (select 'drift', 'booking_lifecycle_notify grants = S111',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_lifecycle_notify' and pg_catalog.pg_get_function_identity_arguments(p.oid) = '') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'atlas_private' and p.proname = 'booking_lifecycle_notify' and pg_catalog.pg_get_function_identity_arguments(p.oid) = ''), 'function missing')) x union all select * from (select 'drift', 'atlas_public_booking_availability body = S111',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_availability' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_date date, p_party_size integer, p_tz text') = '5e7839362c5031f31eb5f0d9dd469707' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_availability' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_date date, p_party_size integer, p_tz text'), 'function missing')) x union all select * from (select 'drift', 'atlas_public_booking_availability grants = S111',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_availability' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_date date, p_party_size integer, p_tz text') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_availability' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_date date, p_party_size integer, p_tz text'), 'function missing')) x union all select * from (select 'drift', 'atlas_public_booking_request body = S111',
  case when (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_request' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_payload jsonb') = '39013189a957c4b78b9ee7f4fbba7736' then 'PASS' else 'FAIL' end,
  coalesce((select 'md5 ' || pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_request' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_payload jsonb'), 'function missing')) x union all select * from (select 'drift', 'atlas_public_booking_request grants = S111',
  case when (select coalesce(p.proacl::text, '') = '{postgres=X/postgres,service_role=X/postgres}' from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_request' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_payload jsonb') then 'PASS' else 'FAIL' end,
  coalesce((select coalesce(p.proacl::text, '') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'atlas_public_booking_request' and pg_catalog.pg_get_function_identity_arguments(p.oid) = 'p_payload jsonb'), 'function missing')) x) d
union all select 4, 'not yet released', 'public seat helpers absent',
  case when not exists (select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'atlas_private' and p.proname in ('booking_public_free_seats', 'booking_public_has_run', 'booking_public_reservation_seats', 'booking_public_seat_ids')) then 'PASS' else 'FAIL' end, ''
union all select 4, 'not yet released', 'owner switch public_instant_confirm absent',
  case when not exists (select 1 from pg_catalog.pg_attribute a where a.attrelid = 'atlas_private.booking_settings'::regclass
    and a.attname = 'public_instant_confirm' and not a.attisdropped) then 'PASS' else 'FAIL' end, ''
union all select 5, 'stools', 'the 16 Bar stools are in their pre-S112 numbering (Bar N = seed N, sections A/B/C)',
  case when (select pg_catalog.count(*) from seed s join atlas_private.booking_tables t on t.id = s.id
              where t.area_id = 'ba000000-0000-4000-8000-000000000001' and t.position_index = s.n and t.label = 'Bar ' || s.n
                and t.segment = case when s.n <= 8 then 'A' when s.n <= 12 then 'B' else 'C' end) = 16 then 'PASS' else 'FAIL' end,
  (select pg_catalog.count(*)::text || ' of 16 match' from seed s join atlas_private.booking_tables t on t.id = s.id
    where t.area_id = 'ba000000-0000-4000-8000-000000000001' and t.position_index = s.n and t.label = 'Bar ' || s.n)
union all select 5, 'stools', 'no other table uses a Bar 1-16 label or position (renumbering needs them free)',
  case when not exists (select 1 from atlas_private.booking_tables t where t.id not in (select id from seed)
      and (t.label ~ '^Bar ([1-9]|1[0-6])( |$)' or (t.area_id = 'ba000000-0000-4000-8000-000000000001' and t.position_index between 1 and 116)))
    then 'PASS' else 'FAIL' end,
  coalesce((select string_agg(t.label, ', ') from atlas_private.booking_tables t where t.id not in (select id from seed)
      and (t.label ~ '^Bar ([1-9]|1[0-6])( |$)' or (t.area_id = 'ba000000-0000-4000-8000-000000000001' and t.position_index between 1 and 116))), 'none')
union all select 6, 'settings', 'online booking switches (S112 adds public_instant_confirm, OFF)', 'INFO',
  (select 'public_online_enabled ' || public_online_enabled || ', auto_confirm ' || auto_confirm
     || ', max_party_online ' || max_party_online from atlas_private.booking_settings where id = true)
union all select 7, 'impact', 'future bookings sitting on Bar stools (their stool numbers change, same physical stools)', 'INFO',
  (select pg_catalog.count(distinct r.id)::text from atlas_private.reservations r
     join atlas_private.reservation_tables rt on rt.reservation_id = r.id and rt.released_at is null
     join seed s on s.id = rt.table_id
    where r.end_at > pg_catalog.now() and r.status in ('confirmed','arrived','seated'))
union all select 8, 'impact', 'future active bookings (all sources)', 'INFO',
  (select pg_catalog.count(*)::text from atlas_private.reservations where start_at > pg_catalog.now()
     and status in ('requested','confirmed','arrived','seated'))
) checks order by ord, "check";
